<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { Users, Megaphone, FileText, Download, CalendarCheck } from '@lucide/vue';
import { teaching, teachingDownload } from '../teachingApi';
import { joinClassroom } from '../api';
const classes=ref<any[]>([]), cid=ref(''), data=ref<any>(null), code=ref(''), error=ref(''), notice=ref(''), loading=ref(false), busy=ref(false);
const applications=ref<any[]>([]);const answers=ref<Record<string,string>>({});let serial=0;
function time(v:string){return new Date(v).toLocaleString('zh-CN',{hour12:false});}
async function load(){loading.value=true;error.value='';try{classes.value=(await teaching('/classes?status=active')).items;applications.value=(await teaching('/join-requests/mine')).items;if(!classes.value.some(c=>c.id===cid.value))cid.value=classes.value[0]?.id||'';await select();}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function select(){const id=++serial;data.value=null;if(!cid.value)return;loading.value=true;try{const result=await teaching(`/classes/${cid.value}/workspace`);if(id===serial){data.value=result;answers.value={};for(const a of result.assignments)answers.value[a.id]=a.submissions[0]?.content||'';}}catch(e){if(id===serial)error.value=(e as Error).message;}finally{if(id===serial)loading.value=false;}}
async function join(){busy.value=true;error.value='';try{await joinClassroom(code.value);code.value='';notice.value='已加入班级';await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function requestJoin(){busy.value=true;error.value='';try{await teaching('/join-requests','POST',{code:code.value});code.value='';notice.value='入班申请已发送，等待教师审核';await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function submit(id:string){busy.value=true;error.value='';try{await teaching(`/classes/${cid.value}/assignments/${id}/submit`,'POST',{content:answers.value[id]});notice.value='提交成功';await select();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function download(r:any){try{await teachingDownload(`/classes/${cid.value}/resources/${r.id}/download`,r.name);}catch(e){error.value=(e as Error).message;}}
onMounted(load);
</script>
<template><div class="student-classes"><header><div><h1><Users :size="30"/>我的班级</h1><p>接收教师公告，完成班级任务，查看个人考勤和教学资料。</p></div><form @submit.prevent="join"><input v-model="code" required maxlength="16" placeholder="输入班级邀请码"/><button :disabled="busy">邀请码加入</button><button type="button" :disabled="busy||!code.trim()" @click="requestJoin">申请加入</button></form></header><p v-if="error" role="alert" class="error">{{error}}<button @click="load">重试</button></p><p v-if="notice" role="status">{{notice}}</p><select v-if="classes.length" v-model="cid" aria-label="选择班级" :disabled="busy" @change="select"><option v-for="c in classes" :key="c.id" :value="c.id">{{c.name}} · {{c.teacher_name}}</option></select><p v-if="loading">正在加载班级内容…</p><p v-else-if="!classes.length" class="empty">尚未加入班级，请向教师获取邀请码。</p><section v-if="applications.length"><h2>我的入班申请</h2><p v-for="a in applications" :key="a.id">{{a.class_name}} · {{({pending:'待教师审核',approved:'已批准',rejected:'未通过'} as any)[a.status]}}</p></section><template v-if="data"><section><h2><Megaphone :size="21"/>班级公告</h2><article v-for="a in data.announcements" :key="a.id"><h3>{{a.pinned?'📌 ':''}}{{a.title}}</h3><small>{{a.teacher_name}} · {{time(a.published_at)}}</small><p class="preserve">{{a.content}}</p></article><p v-if="!data.announcements.length" class="empty">暂无已发布公告</p></section><section><h2><FileText :size="21"/>作业与学习任务</h2><article v-for="a in data.assignments" :key="a.id"><h3>{{a.title}}</h3><small>{{a.kind==='task'?'学习任务':'作业与测试'}} · 截止 {{time(a.due_at)}}</small><p class="preserve">{{a.content}}</p><form @submit.prevent="submit(a.id)"><textarea v-model="answers[a.id]" rows="4" required maxlength="20000" :disabled="busy || new Date(a.due_at).getTime()<Date.now()" placeholder="填写作答或任务完成说明"/><button :disabled="busy || new Date(a.due_at).getTime()<Date.now()">{{a.submissions[0]?.submitted_at?'重新提交':'提交作答'}}</button></form><p v-if="a.submissions[0]?.submitted_at">提交时间 {{time(a.submissions[0].submitted_at)}} · 成绩 {{a.submissions[0].score ?? '待教师批改'}}</p><p v-if="a.submissions[0]?.feedback">教师评语：{{a.submissions[0].feedback}}</p></article><p v-if="!data.assignments.length" class="empty">暂无分配给你的作业或任务</p></section><section><h2><CalendarCheck :size="21"/>个人考勤历史</h2><article v-for="a in data.attendance.filter((a:any)=>a.completed&&a.records.length)" :key="a.id"><strong>{{a.attendance_date}} · {{a.title}}</strong><p>{{({present:'出勤',late:'迟到',leave:'请假',absent:'缺勤'} as any)[a.records[0].status]}}</p></article><p v-if="!data.attendance.some((a:any)=>a.completed&&a.records.length)" class="empty">暂无个人考勤记录</p></section><section><h2>班级资料</h2><article v-for="r in data.resources" :key="r.id" class="resource"><div><strong>{{r.name}}</strong><p>{{r.category}} · {{(r.size/1024).toFixed(1)}} KB</p></div><button @click="download(r)"><Download :size="16"/>下载</button></article><p v-if="!data.resources.length" class="empty">暂无公开教学资料</p></section><section><h2>我的学习小组</h2><p v-for="g in data.groups" :key="g.student_id">{{g.name}} · {{g.student_name}}{{g.student_id===g.leader_id?'（组长）':''}}</p><p v-if="!data.groups.length" class="empty">尚未加入学习小组</p></section></template></div></template>
<style scoped>.student-classes{display:grid;gap:16px;color:#102a56}.student-classes>header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px;border-radius:20px;background:linear-gradient(120deg,#e3efff,#cedfff)}h1,h2{display:flex;align-items:center;gap:10px;margin:0 0 12px}h1{font-size:28px}h2{font-size:20px}h3{font-size:17px;margin:0 0 10px}section{background:#ffffffdf;border:1px solid white;border-radius:18px;padding:22px;min-width:0}article{padding:18px;background:#f7faff;border:1px solid #e2ebfa;border-radius:13px;margin:14px 0}p{line-height:1.8;color:#536b91}small{font-size:12px;color:#64748b}button{display:inline-flex;align-items:center;gap:6px;padding:10px 15px;border:0;border-radius:10px;background:#155eef;color:white;cursor:pointer;font:inherit;font-size:13px}button:disabled{opacity:.5;cursor:not-allowed}input,textarea,select{font:inherit;padding:10px 12px;border:1px solid #d3e2ff;border-radius:10px;background:white;color:#102a56;max-width:100%;box-sizing:border-box}textarea{display:block;width:100%;margin-bottom:12px}form{display:flex;flex-wrap:wrap;gap:10px}article form{display:block}.empty{text-align:center;padding:30px;color:#64748b}.error{color:#b42318;background:#fff0f0;padding:12px;border-radius:12px}.preserve{white-space:pre-wrap;overflow-wrap:anywhere}.resource{display:flex;align-items:center;justify-content:space-between;gap:10px}@media(max-width:700px){.student-classes>header{align-items:flex-start;flex-direction:column}section{padding:16px}.resource{flex-wrap:wrap}}</style>
